from src_europe1 import M, add

# ---- Netherlands, Belgium
add(slug="rijksmuseum", name="Rijksmuseum", wiki="Rijksmuseum", city="Amsterdam", country="Netherlands", continent="Europe",
 aliases=["Rijksmuseum"], founded="1800",
 desc="The national museum of the Netherlands holds the great art of the Dutch Golden Age: Rembrandt's Night Watch, Vermeer's Milkmaid and hundreds of other paintings of the 1600s, in a fairy-tale brick building with a cycle path running through it.",
 history="The Dutch government founded a national art gallery in The Hague in 1800 and moved the collection to Amsterdam in 1808, where King Louis Napoleon, Napoleon's brother, made it a royal museum. The present red-brick building by Pierre Cuypers opened in 1885. A ten-year renovation closed most of the museum from 2003 to 2013, and it reopened to huge crowds. The Night Watch has its own room, and in 2019 a team began a public scientific restoration of it, which visitors can watch.",
 highlights=[("The Night Watch","Rembrandt",1642),("The Milkmaid","Johannes Vermeer",1658),("The Little Street","Johannes Vermeer",1658),("The Merry Drinker","Frans Hals",1628),("The Jewish Bride","Rembrandt",1665)])
add(slug="van-gogh-museum", name="Van Gogh Museum", wiki="Van Gogh Museum", city="Amsterdam", country="Netherlands", continent="Europe",
 aliases=["Van Gogh Museum"], founded="1973",
 desc="The world's largest collection of Van Gogh's paintings and drawings, with about 200 paintings, is in a modern building beside the Rijksmuseum, along with his letters and works by his friends.",
 history="After Vincent van Gogh's death in 1890, his brother Theo and then Theo's wife, Johanna van Gogh-Bonger, kept and promoted the art. Vincent's nephew, also named Vincent, a young engineer, agreed in 1962 that the Dutch state would build a museum for the collection. The Van Gogh Museum, designed by Gerrit Rietveld, opened in 1973. A new wing designed by Kisho Kurokawa opened in 1999.",
 highlights=[("The Potato Eaters","Vincent van Gogh",1885),("Sunflowers","Vincent van Gogh",1889),("The Bedroom","Vincent van Gogh",1888),("Almond Blossom","Vincent van Gogh",1890)])
add(slug="mauritshuis", name="Mauritshuis", wiki="Mauritshuis", city="The Hague", country="Netherlands", continent="Europe",
 aliases=["Mauritshuis"], founded="1822",
 desc="A small, elegant 17th-century mansion in The Hague holds some of the most famous paintings in the Netherlands: Vermeer's Girl with a Pearl Earring, Rembrandt's Anatomy Lesson of Dr. Tulp and Fabritius's Goldfinch.",
 history="Johan Maurits, a Dutch governor in Brazil, had the house built in the 1640s. It became a museum in 1822, when the Dutch government bought it to show the royal art collection. In 2014 it reopened after a two-year renovation and a new underground extension. Donna Tartt's novel The Goldfinch, from 2013, made one of its paintings famous.",
 highlights=[("Girl with a Pearl Earring","Johannes Vermeer",1665),("View of Delft","Johannes Vermeer",1660),("The Anatomy Lesson of Dr. Nicolaes Tulp","Rembrandt",1632),("The Goldfinch","Carel Fabritius",1654)])
add(slug="kroller-muller", name="Kröller-Müller Museum", wiki="Kröller-Müller Museum", city="Otterlo", country="Netherlands", continent="Europe",
 aliases=["Kröller-Müller Museum"], founded="1938",
 desc="A museum in the middle of a big national park, with the second-largest collection of Van Gogh in the world, as well as works by Seurat and Mondrian and a great sculpture garden.",
 history="Helene Kröller-Müller, who was the wife of a shipping tycoon, began to collect art in 1907 on the advice of an art teacher. She was among the first to buy Van Gogh's paintings in large numbers. In 1935 she gave her collection to the Dutch state, and the museum opened in 1938 in the woods of the Hoge Veluwe. The sculpture garden, one of the biggest in Europe, grew after the Second World War.",
 highlights=[("Café Terrace at Night","Vincent van Gogh",1888),("Le Chahut","Georges Seurat",1890)])
add(slug="kunstmuseum-den-haag", name="Kunstmuseum Den Haag", wiki="Kunstmuseum Den Haag", city="The Hague", country="Netherlands", continent="Europe",
 aliases=["Kunstmuseum Den Haag"], founded="1866",
 desc="The art museum of The Hague, in an elegant brick building by the architect Berlage, holds the largest collection of Piet Mondrian's work in the world, including his last paintings, Victory Boogie Woogie.",
 history="The museum started in 1866 as a municipal collection and moved to a building by H. P. Berlage, which opened in 1935. Mondrian, who was Dutch, spent much of his life in Paris, London and New York, and his friend Salomon Slijper kept a big group of his paintings, which came to the museum in 1946, so that the museum could trace his path from landscapes to pure abstraction.",
 highlights=[("Victory Boogie Woogie","Piet Mondrian",1944),("Composition with Large Red Plane, Yellow, Black, Grey and Blue","Piet Mondrian",1921)])
add(slug="rmfab", name="Royal Museums of Fine Arts of Belgium", wiki="Royal Museums of Fine Arts of Belgium", city="Brussels", country="Belgium", continent="Europe",
 aliases=["Royal Museums of Fine Arts of Belgium"], founded="1801",
 desc="A group of connected museums in the heart of Brussels, with Old Masters of the Low Countries, Rubens, Bruegel, Magritte, David's Death of Marat and a fine Belgian modern collection.",
 history="Napoleon's government founded a museum in Brussels in 1801, which grew into the Royal Museums with a new neoclassical building in 1887. The Magritte Museum, with the world's biggest collection of the Belgian Surrealist René Magritte, was added in 2009. David came to Brussels when he was exiled from France after Napoleon fell.",
 highlights=[("The Death of Marat","Jacques-Louis David",1793),("Landscape with the Fall of Icarus","Pieter Bruegel the Elder (attributed)",1558)])
add(slug="kmska", name="Royal Museum of Fine Arts Antwerp (KMSKA)", wiki="Royal Museum of Fine Arts Antwerp", city="Antwerp", country="Belgium", continent="Europe",
 aliases=["Royal Museum of Fine Arts Antwerp"], founded="1810",
 desc="Antwerp's big museum has a collection of six centuries of Flemish art, from Jean Fouquet to Rubens and James Ensor, in a great building that reopened in 2022 after a long renovation.",
 history="The museum has its roots in 1810, when Napoleon returned paintings that had been taken to Paris to Antwerp. It was housed in its present building from 1890 and was closed for 11 years for a restoration that ended in 2022. Rubens, who lived and worked in Antwerp, is the museum's star.",
 highlights=[("Virgin and Child (Melun Diptych)","Jean Fouquet",1455),("Adoration of the Magi","Peter Paul Rubens",1624)])

# ---- Germany
add(slug="alte-pinakothek", name="Alte Pinakothek", wiki="Alte Pinakothek", city="Munich", country="Germany", continent="Europe",
 aliases=["Alte Pinakothek"], founded="1836",
 desc="One of the world's oldest and greatest galleries of Old Master paintings, with works by Dürer, Rubens, Rembrandt, Raphael and Leonardo, housed in a huge brick-red building in the museum quarter of Munich.",
 history="King Ludwig I of Bavaria wanted to open the royal collections to the public, and he had the architect Leo von Klenze build the museum, which opened in 1836. It was one of the largest museums in the world when it was built, and many later galleries copied its design. It was badly damaged in the Second World War and rebuilt in the 1950s.",
 highlights=[("Self-Portrait at Twenty-Eight","Albrecht Dürer",1500),("Madonna of the Carnation","Leonardo da Vinci",1478)])
add(slug="lenbachhaus", name="Lenbachhaus", wiki="Lenbachhaus", city="Munich", country="Germany", continent="Europe",
 aliases=["Lenbachhaus","Städtische Galerie im Lenbachhaus"], founded="1929",
 desc="A villa in Munich with the world's most important collection of the Blue Rider group, including Kandinsky, Marc, Macke and Gabriele Münter, who brought their colors to modern art.",
 history="The painter Franz von Lenbach built the Italian-style villa in 1887, and after his death it became a city gallery in 1929. In 1957 Gabriele Münter, Kandinsky's partner, gave the museum about a thousand works by Kandinsky and her friends that she had hidden from the Nazis. The villa was expanded with a golden-colored extension in 2013.",
 highlights=[("Blue Horse I","Franz Marc",1911),("Red Spot II","Wassily Kandinsky",1921)])
add(slug="gemaldegalerie-berlin", name="Gemäldegalerie, Berlin", wiki="Gemäldegalerie, Berlin", city="Berlin", country="Germany", continent="Europe",
 aliases=["Gemäldegalerie","Gemäldegalerie, Berlin"], founded="1830",
 desc="Berlin's collection of European paintings from the 1200s to the 1700s has Vermeer, Rembrandt, Bruegel, Dürer and Botticelli, in a sleek modern gallery at the Kulturforum.",
 history="The collection began with the Prussian royal art collection, which was opened to the public in the Altes Museum in 1830. After the Second World War it was divided between East and West Berlin, and was reunited in 1998 in a new building. Many of its masterpieces had been hidden in mines and bunkers during the war.",
 highlights=[("Woman with a Pearl Necklace","Johannes Vermeer",1664),("Netherlandish Proverbs","Pieter Bruegel the Elder",1559)])
add(slug="alte-nationalgalerie", name="Alte Nationalgalerie", wiki="Alte Nationalgalerie", city="Berlin", country="Germany", continent="Europe",
 aliases=["Alte Nationalgalerie"], founded="1876",
 desc="A temple-like gallery on Berlin's Museum Island, with German and French art of the 1800s: Caspar David Friedrich's Romantic paintings, Menzel, Böcklin and the Impressionists.",
 history="The building was designed by Friedrich August Stüler and Johann Heinrich Strack and opened in 1876 for paintings of the 'present', 19th-century art, with the help of a donation by the banker Joachim Wagener. It was damaged in the Second World War and reopened in 2001 after a major restoration. It is part of the UNESCO World Heritage Site of Museum Island.",
 highlights=[("Monk by the Sea","Caspar David Friedrich",1810),("Frederick the Great Playing the Flute at Sanssouci","Adolph von Menzel",1852)])
add(slug="hamburger-kunsthalle", name="Hamburger Kunsthalle", wiki="Hamburger Kunsthalle", city="Hamburg", country="Germany", continent="Europe",
 aliases=["Hamburger Kunsthalle"], founded="1869",
 desc="Hamburg's art museum is known for German Romantic painting and holds Caspar David Friedrich's masterpiece, Wanderer above the Sea of Fog.",
 history="The museum was founded by citizens of Hamburg and opened in 1869 in a building by Georg Theodor Schirrmacher and Hermann von der Hude. It has been extended several times, and a new cube-shaped building opened in 1997 for modern art. The Friedrich collection is its pride.",
 highlights=[("Wanderer above the Sea of Fog","Caspar David Friedrich",1818)])
add(slug="dresden-old-masters", name="Gemäldegalerie Alte Meister (Dresden)", wiki="Gemäldegalerie Alte Meister", city="Dresden", country="Germany", continent="Europe",
 aliases=["Gemäldegalerie Alte Meister","Albertinum"], founded="1560",
 desc="The Zwinger palace in Dresden houses a gallery of Old Masters that is home to Raphael's Sistine Madonna, famous for the two little angels at the bottom.",
 history="The painting collection goes back to the 1500s and the rulers of Saxony, who were great collectors. In the 1740s Augustus III bought masterpieces including the Sistine Madonna. The Zwinger gallery was built in the 1850s by Gottfried Semper, and the paintings were hidden during the bombing of Dresden in 1945, then taken by the Soviet army and returned to Dresden in 1955.",
 highlights=[("Sistine Madonna","Raphael",1512),("Girl Reading a Letter at an Open Window","Johannes Vermeer",1659)])
add(slug="staedel", name="Städel Museum", wiki="Städel", city="Frankfurt", country="Germany", continent="Europe",
 aliases=["Städel Museum"], founded="1815",
 desc="Frankfurt's art museum holds 700 years of European art, from the Middle Ages to today, with work by Vermeer, Botticelli, Monet and Beckmann.",
 history="The banker Johann Friedrich Städel left his art collection and fortune in 1815 to found an art institute, one of the first museums in Germany created by a private citizen rather than a ruler. The museum grew with gifts from citizens of Frankfurt. A garden hall for modern art was built beneath the museum's courtyard in 2012.",
 highlights=[("The Geographer","Johannes Vermeer",1669)])

# ---- Austria, Switzerland, Czechia, Poland
add(slug="khm", name="Kunsthistorisches Museum", wiki="Kunsthistorisches Museum", city="Vienna", country="Austria", continent="Europe",
 aliases=["Kunsthistorisches Museum"], founded="1891",
 desc="Vienna's great museum holds the Habsburg dynasty's art, including the world's largest collection of Pieter Bruegel the Elder, with his Tower of Babel and Hunters in the Snow, as well as Vermeer's Art of Painting.",
 history="The Habsburg emperors, who ruled much of Europe, collected for centuries. Emperor Franz Joseph ordered a pair of matching museums to be built on the Ringstrasse, and the Kunsthistorisches Museum opened in 1891, facing a twin building for natural history. The sumptuous interior has paintings by Klimt in the stairwell.",
 highlights=[("The Tower of Babel","Pieter Bruegel the Elder",1563),("Hunters in the Snow","Pieter Bruegel the Elder",1565),("The Art of Painting","Johannes Vermeer",1666)])
add(slug="belvedere", name="Belvedere", wiki="Belvedere, Vienna", city="Vienna", country="Austria", continent="Europe",
 aliases=["Belvedere"], founded="1903",
 desc="A pair of baroque palaces with beautiful gardens in Vienna, which hold the world's largest collection of Gustav Klimt, including The Kiss.",
 history="Prince Eugene of Savoy, a famous general, had the Belvedere palaces built in the early 1700s. The imperial art collection was displayed here from 1781. Since 1903 the palace has also housed a modern gallery, which bought Klimt's The Kiss in 1908 straight from his studio, when it was first shown, for a huge sum.",
 highlights=[("The Kiss","Gustav Klimt",1908),("Judith","Gustav Klimt",1901),("Death and the Maiden","Egon Schiele",1915)])
add(slug="leopold", name="Leopold Museum", wiki="Leopold Museum", city="Vienna", country="Austria", continent="Europe",
 aliases=["Leopold Museum"], founded="2001",
 desc="A modern white limestone cube in Vienna's MuseumsQuartier shows the largest collection of Egon Schiele paintings in the world, and important works by Klimt and Vienna's Secession artists.",
 history="Rudolf Leopold, a doctor and collector, spent his life buying works by Egon Schiele when they were unfashionable. In 1994 the Austrian government bought his collection, with around 5,000 pieces, for a foundation, and the museum, designed by Ortner & Ortner, opened in 2001.",
 highlights=[("Self-Portrait with Chinese Lantern Plant","Egon Schiele",1912),("Wally","Egon Schiele",1912)])
add(slug="kunstmuseum-basel", name="Kunstmuseum Basel", wiki="Kunstmuseum Basel", city="Basel", country="Switzerland", continent="Europe",
 aliases=["Kunstmuseum Basel"], founded="1661",
 desc="The oldest public art collection in the world has Holbein and Cranach, Picasso and Klee in two buildings in the Swiss city of Basel.",
 history="In 1661 the city of Basel bought the collection of the Amerbach family, the first time that a private art collection was bought for the public. That is why Basel's museum is said to be the oldest public art museum in the world. It has the world's biggest collection of the painter Hans Holbein the Younger, and its modern wing is famous for Picasso.",
 highlights=[("The Fate of the Animals","Franz Marc",1913)])
add(slug="kunsthaus-zurich", name="Kunsthaus Zürich", wiki="Kunsthaus Zürich", city="Zürich", country="Switzerland", continent="Europe",
 aliases=["Kunsthaus Zürich"], founded="1910",
 desc="Zürich's art museum holds the largest collection of Edvard Munch outside Norway, plus Monet, Giacometti and a big collection of Swiss art.",
 history="The Zürich Art Society built the museum, designed by Karl Moser, which opened in 1910. The Swiss collection of Alberto Giacometti was added over time, and so was the Foundation E. G. Bührle Collection of Impressionist paintings in a 2021 extension by David Chipperfield.",
 highlights=[])
add(slug="ng-prague", name="National Gallery Prague (Trade Fair Palace)", wiki="National Gallery Prague", city="Prague", country="Czechia", continent="Europe",
 aliases=["Trade Fair Palace"], founded="1796",
 desc="The national art museum of the Czech Republic has several buildings in Prague, and its big Veletržní Palace holds modern art of the 1800s and 1900s, with Czech painters, and Klimt, Schiele and Picasso.",
 history="A group of Czech nobles founded a society to promote art in 1796, which led to the National Gallery. The modern art is housed in the Trade Fair Palace, a huge functionalist building of the 1920s, which became a gallery in 1995.",
 highlights=[])
add(slug="mnw-warsaw", name="National Museum in Warsaw", wiki="National Museum, Warsaw", city="Warsaw", country="Poland", continent="Europe",
 aliases=["National Museum in Warsaw"], founded="1862",
 desc="Poland's biggest art museum has Polish painting from the Middle Ages to today, with Jan Matejko's giant Battle of Grunwald, and also works from ancient Egypt and Europe.",
 history="The museum was founded in 1862 while Poland was divided among foreign powers, as a place where Polish culture could be shown. Its modern building opened in 1938, but in the Second World War the Nazis looted and destroyed much of the collection. After the war many works were recovered, and the museum has restored Matejko's Battle of Grunwald, one of the largest paintings in Poland.",
 highlights=[("Battle of Grunwald","Jan Matejko",1878)])
add(slug="mnk-krakow", name="National Museum in Kraków", wiki="National Museum, Kraków", city="Kraków", country="Poland", continent="Europe",
 aliases=["National Museum in Kraków"], founded="1879",
 desc="Kraków's national museum has Polish art in the beautiful Cloth Hall in the main square, and it also includes the Czartoryski Museum, which holds Leonardo da Vinci's Lady with an Ermine.",
 history="The museum began in 1879, when the city gave its collection a home, and its Gallery of 19th-Century Polish Art in the Cloth Hall in the main square opened in 1879. In 2016 the Czartoryski Foundation's collections were bought by the Polish state and joined the museum.",
 highlights=[("Lady with an Ermine","Leonardo da Vinci",1490),("Prussian Homage","Jan Matejko",1882)])

# ---- Russia
add(slug="hermitage", name="The State Hermitage Museum", wiki="Hermitage Museum", city="Saint Petersburg", country="Russia", continent="Europe",
 aliases=["Hermitage Museum","Winter Palace"], founded="1764",
 desc="One of the largest art museums in the world fills the Winter Palace of the tsars and four other buildings on the Neva river, with about three million objects, including Rembrandt, Leonardo, Matisse and Picasso.",
 history="Catherine the Great began the Hermitage in 1764 by buying a collection of 225 paintings from Berlin, and she kept adding to it, buying whole collections of European masters. It became a public museum only in 1852. After the revolution in 1917 the Winter Palace became part of the museum, and the Soviet government added art taken from private collectors, such as the Impressionists of Shchukin and Morozov. During the siege of Leningrad of 1941 to 1944 the staff hid the art and stayed in the basement.",
 highlights=[("The Return of the Prodigal Son","Rembrandt",1669),("The Dance","Henri Matisse",1910),("Benois Madonna","Leonardo da Vinci",1480)])
add(slug="tretyakov", name="State Tretyakov Gallery", wiki="Tretyakov Gallery", city="Moscow", country="Russia", continent="Europe",
 aliases=["State Tretyakov Gallery"], founded="1856",
 desc="The national gallery of Russian art, in a fairy-tale building in Moscow, holds the best of Russian painting, including Repin, Shishkin, Vrubel and Malevich's original Black Square.",
 history="The Moscow merchant Pavel Tretyakov began buying Russian paintings in 1856 and decided to give them to the city. In 1892 he donated his collection of about 1,300 paintings, and the gallery opened to the public. Tretyakov's house was rebuilt with the folk-style facade by Viktor Vasnetsov. After the revolution it became a state museum.",
 highlights=[("Ivan the Terrible and His Son Ivan","Ilya Repin",1885),("Morning in a Pine Forest","Ivan Shishkin",1889),("Black Square","Kazimir Malevich",1915)])
add(slug="pushkin", name="Pushkin Museum of Fine Arts", wiki="Pushkin Museum", city="Moscow", country="Russia", continent="Europe",
 aliases=["Pushkin Museum of Fine Arts"], founded="1912",
 desc="Moscow's main museum of European art has masterpieces by Botticelli, Rembrandt, Monet and Van Gogh, in a classical building near the Kremlin. It is named after the poet Alexander Pushkin.",
 history="The museum was founded in 1912 by the professor Ivan Tsvetaev as a place for students to study casts of famous sculptures. After the revolution, the Soviet government gave it large collections of paintings seized from Russian collectors, including the Impressionist and modern paintings of Sergei Shchukin and Ivan Morozov, which the Pushkin Museum shares with the Hermitage.",
 highlights=[("Prisoners Exercising","Vincent van Gogh",1890)])
add(slug="russian-museum", name="State Russian Museum", wiki="Russian Museum", city="Saint Petersburg", country="Russia", continent="Europe",
 aliases=["Russian Museum"], founded="1895",
 desc="The world's biggest collection of Russian art is in an elegant palace in Saint Petersburg and has masterpieces by Repin, Aivazovsky, Bryullov and Kandinsky.",
 history="Tsar Alexander III wanted a national museum of Russian art, and after his death in 1894 Tsar Nicholas II opened the Russian Museum in the Mikhailovsky Palace in 1898. It grew after the revolution, with gifts from famous painters. It's the home of Repin's Reply of the Zaporozhian Cossacks and Bryullov's Last Day of Pompeii.",
 highlights=[("The Last Day of Pompeii","Karl Bryullov",1833),("The Ninth Wave","Ivan Aivazovsky",1850),("Reply of the Zaporozhian Cossacks","Ilya Repin",1891)])

# ---- Nordic, Ireland
add(slug="nasjonalmuseet", name="Nasjonalmuseet (National Museum, Oslo)", wiki="National Museum of Art, Architecture and Design", city="Oslo", country="Norway", continent="Europe",
 aliases=["National Museum of Art, Architecture and Design"], founded="1837",
 desc="Norway's national museum, the largest art museum in the Nordic countries, opened a vast new building on the Oslo waterfront in 2022. It has Munch's The Scream and the best paintings of Norway's fjords, mountains and troll tales.",
 history="Norway founded its national gallery in 1837, soon after it became independent of Denmark in 1814, in order to show the new nation's art and culture. The collection was housed in several places. In 2022 the National Museum opened in a new building by the architect Klaus Schuwerk, on the harbor in Oslo, merging four museums into one, and it is the biggest museum building in the Nordic region.",
 highlights=[("The Scream","Edvard Munch",1893),("Bridal Procession on the Hardangerfjord","Adolph Tidemand and Hans Gude",1848),("Starry Night","Edvard Munch",1893)])
add(slug="munch-museum", name="MUNCH (Munch Museum)", wiki="Munch Museum", city="Oslo", country="Norway", continent="Europe",
 aliases=["Munch Museum"], founded="1963",
 desc="A tall, tilted museum on the Oslo waterfront holds the world's largest collection of Edvard Munch, about 28,000 works, including another version of The Scream.",
 history="Edvard Munch left all the paintings, prints and drawings in his possession to the city of Oslo when he died in 1944. The Munch Museum opened in 1963 to mark the centenary of his birth. In 2021 it moved into a large new building on the Bjørvika waterfront, a 13-story tower of aluminum panels. In 2004 thieves stole The Scream and Madonna from the old museum, and the paintings were recovered two years later.",
 highlights=[("The Scream","Edvard Munch",1910),("Madonna","Edvard Munch",1895)])
add(slug="nationalmuseum-stockholm", name="Nationalmuseum", wiki="Nationalmuseum", city="Stockholm", country="Sweden", continent="Europe",
 aliases=["Nationalmuseum"], founded="1792",
 desc="Sweden's national museum of art holds Rembrandt, Rubens, the Swedish painters Carl Larsson and Anders Zorn, and a famous Scandinavian design collection, in a Renaissance-style palace by the water.",
 history="The Swedish king Gustav III opened the royal collection to the public as the Royal Museum in 1792, and the present building on Blasieholmen, designed by the German architect Friedrich August Stüler, opened in 1866. In 2018 it reopened after a five-year renovation. Carl Larsson's giant mural Midwinter Sacrifice was painted for its stairway in 1915.",
 highlights=[("The Conspiracy of Claudius Civilis","Rembrandt",1661),("Midwinter Sacrifice","Carl Larsson",1915)])
add(slug="smk", name="Statens Museum for Kunst (SMK)", wiki="Statens Museum for Kunst", city="Copenhagen", country="Denmark", continent="Europe",
 aliases=["Statens Museum for Kunst"], founded="1896",
 desc="Denmark's national gallery in Copenhagen has the best of Danish art, including the calm interiors of Hammershøi and Golden Age painters like Eckersberg, as well as European masters and Matisse.",
 history="The Danish royal collections were opened to the public in 1827, and the present building on Sølvgade was finished in 1896. A modern extension by Anna Maria Indrio opened in 1998. The collection is full of paintings from the Danish Golden Age of the early 1800s.",
 highlights=[])
add(slug="ateneum", name="Ateneum", wiki="Ateneum", city="Helsinki", country="Finland", continent="Europe",
 aliases=["Ateneum"], founded="1887",
 desc="Finland's main art museum is in a lovely neoclassical building opposite Helsinki's railway station, with Finnish paintings of the Golden Age by Akseli Gallen-Kallela and Albert Edelfelt, as well as Van Gogh and Cézanne.",
 history="The Ateneum was built in 1887 as the home of the Finnish Art Society, an art school and a museum in one. Finnish artists in the 1890s, such as Akseli Gallen-Kallela, found their national style in the Finnish folk epic, the Kalevala, and these paintings now hang here. The museum is part of the Finnish National Gallery.",
 highlights=[("The Aino Myth (triptych)","Akseli Gallen-Kallela",1891)])
add(slug="skagens-museum", name="Skagens Museum", wiki="Skagens Museum", city="Skagen", country="Denmark", continent="Europe",
 aliases=["Skagens Museum"], founded="1908",
 desc="A museum at the northern tip of Denmark where the sea and sky meet, devoted to the Skagen Painters, a group of Scandinavian artists who painted summer light on the beach.",
 history="Artists including P. S. Krøyer, Anna and Michael Ancher and Laurits Tuxen settled in the fishing village of Skagen in the 1870s and 1880s and painted the sea, the fishermen and the long summer evenings. They founded the Skagens Museum in 1908, and it opened in a yellow building on the town square. It holds the world's biggest collection of their work.",
 highlights=[("Summer Evening on Skagen's Southern Beach","P. S. Krøyer",1893)])
add(slug="ngi", name="National Gallery of Ireland", wiki="National Gallery of Ireland", city="Dublin", country="Ireland", continent="Europe",
 aliases=["National Gallery of Ireland"], founded="1864",
 desc="Dublin's free national gallery has Irish and European art, including a lost Caravaggio that was found in a monastery dining room, and it has a big collection of paintings by Jack B. Yeats.",
 history="The gallery opened in 1864 on Merrion Square. The writer George Bernard Shaw, who said the gallery had given him his education, left it a third of his royalties, and money from his play Pygmalion and the musical My Fair Lady paid for many purchases. In 1990 a missing Caravaggio, The Taking of Christ, was identified on the wall of a Jesuit house in Dublin and given to the gallery.",
 highlights=[("The Taking of Christ","Caravaggio",1602),("Lady Writing a Letter with Her Maid","Johannes Vermeer",1670)])
